  /// 指定の級の演習で出す語（その級以下の字だけの語。上の級ほど、やさしい級の語も出る）。
  /// 準1級・1級（_rank に無い級）は、全部の語。
  static List<CompoundQuestion> forLevel(String level) {
    final rank = _rank[level] ?? 0;
    return all.where((q) => (_rank[q.level] ?? 0) >= rank).toList();
  }
